(async()=>{'use strict';
const b64=(window.__RMS||[]).join('');const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));let text;try{const ds=new DecompressionStream('gzip');text=await new Response(new Blob([bytes]).stream().pipeThrough(ds)).text()}catch(e){document.body.innerHTML='<p style="padding:2rem">この試作サイトの展開に失敗しました。新しいブラウザで開いてください。</p>';throw e}const data=JSON.parse(text);const path=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';const page=data.pages[path]||data.pages['/'];document.title=page.title;document.querySelector('meta[name=description]').content=page.desc;document.body.className=page.bodyClass;const style=document.createElement('style');style.textContent=data.css;document.head.append(style);const nav=[['製品情報','/products/'],['霊務品質','/quality/'],['研究・開発','/research/'],['ブランドサイト','/#brands'],['ニュース','/news/'],['制作者','/creator/']];const header=`<a class="skip" href="#main">本文へ</a><div class="noticebar"><span>NEWS</span><a href="/news/">霊務製品の試験販売と個別発行について、配信内で先行案内中</a></div><header class="site-header"><a class="logo" href="/"><span class="logo-mark">全歯</span><span><b>すべての歯が見える</b><small>霊務技術・異物製品</small></span></a><button class="menu-button" aria-expanded="false" aria-controls="global-nav">MENU</button><nav id="global-nav" class="global-nav" aria-label="主要メニュー">${nav.map(([l,h])=>`<a class="${l===page.active?'is-active':''}" href="${h}">${l}</a>`).join('')}</nav><div class="header-actions"><a href="/members/">霊務記録閲覧室</a><a class="shop-link" href="/products/">製品を探す</a></div></header>`;const footer=`<footer class="site-footer"><div class="footer-brand"><span class="logo-mark">全歯</span><div><b>すほての歯が見える</b><p>霊務技術・異物製品の研究、設計、制作、記録。</p></div></div><div class="footer-grid"><div><h3>製品</h3><a href="/brands/imoji/">妹字</a><a href="/brands/shikigami/">式神</a><a href="/brands/jutsushiki/">術式・鑑定</a><a href="/brands/kuro-teruteru/">黒いてるてる坊主</a></div><div><h3>会社のようなもの</h3><a href="/quality/">霊務品質</a><a href="/research/">研究・開発</a><a href="/creator/">制作者</a><a href="/private-room/">制作者の私室</a></div><div><h3>記録</h3><a href="/works/">特設ページ保管庫</a><a href="/news/">ニュース</a><a href="/members/">霊務記録閲覧室</a></div></div><div class="footer-bottom"><small>本サイトは試作版です。掲載画像は仮ビジュアルであり、実物商品の写真ではありません。</small><small>© 2026 すべての歯が見える</small></div></footer>`;document.body.innerHTML=header+`<main id="main">${page.main}</main>`+footer;const menu=document.querySelector('.menu-button'),gn=document.querySelector('.global-nav');menu?.addEventListener('click',()=>{const on=gn.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(on))});const slides=[...document.querySelectorAll('[data-slide]')],cur=document.querySelector('[data-current]');let i=0;const show=n=>{if(!slides.length)return;slides[i].classList.remove('is-active');i=(n+slides.length)%slides.length;slides[i].classList.add('is-active');if(cur)cur.textContent=String(i+1).padStart(2,'0')};document.querySelector('[data-next]')?.addEventListener('click',()=>show(i+1));document.querySelector('[data-prev]')?.addEventListener('click',()=>show(i-1));const bar=document.querySelector('[data-filterbar]');bar?.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;bar.querySelectorAll('button').forEach(x=>x.classList.remove('is-active'));b.classList.add('is-active');const f=b.dataset.filter;document.querySelectorAll('[data-kind]').forEach(c=>c.hidden=f!=='all'&&c.dataset.kind!==f)});const form=document.querySelector('[data-login-demo]');form?.addEventListener('submit',e=>{e.preventDefault();form.querySelector('[data-login-message]').textContent='これはUI見本のため、メールは送信されません。本実装では招待制認証へ接続します。'});document.documentElement.dataset.ready='true';})();